    badgeDelegationB3Desc: 'Павесьце дэлегаваны значок у любым месцы праграмы, і ў ім пазначце, хто яго падтрымлівае. Нічога не схавана, адкуль узяўся ярус.',
    badgeDelegationB4: 'Рэверсіўны ў любы час:',
    badgeDelegationB4Desc: 'Вазьміце слот назад, і ўзровень вернецца да вас. Ваша ўласная стаўка, узровень платы і значок замкнёны не закрануты чым-небудзь, што вы пазычаеце.',
    badgeDelegationB5: 'Статус, а не правы:',
    badgeDelegationB5Desc: 'Пазычальны знак - гэта тое, што паказвае платформа, і ён нясе вагу, які ідзе з узроўнем — выгляд або рэакцыя ад яго ўлічваецца на ўзроўні, які ён быў пазычаны. Тое, што ён не нясе, - гэта грошы: ваш узровень платы, зніжка на куплю жэтонаў, штодзённая норма размяшчэння і ўласныя слоты для дэлегацыі.',
    badgeDelegationB6: 'Пакладзіце любы прыступ, на які вы падняліся:',
    badgeDelegationB6Desc: 'Слот не павінен здаваць ваш верхні ўзровень. Вазьмі разблакаваны пярсцёнак, які ён пазычае, і вярні кагосьці каралю Кобры, не робячы іх Мегаладонам.',
    badgeDelegationB7: 'На другім баку ёсць выраз:',
    badgeDelegationB7Desc: 'У званочку апавяшчэння з \'явіцца прапанаваны ўліковага запісу значок, і яны могуць яго адхіліць. Любы з вас можа скончыць дэлегацыю пазней.',
    tipTitle: 'Наканечнік вашых фаварытаў',
    tipDesc1: 'Нашы інтэграваныя паслугі перанакіравання на ўсе загрузкі і прамыя трансляцыі плацяць толькі 10% у параўнанні з звычайнымі 60%, якія спаганяюцца падобнымі TikTok і іншымі лідэрамі галіны, а таксама маюць магчымасць галасаваць за адмену відэа, вярнуўшы ўлада ў рукі гледача.',
    tipDesc2: 'Парады, атрыманыя для стваральнікаў, і парады, дадзеныя гледачамі, увайшлі ў асобныя спісы лідэраў разам з падлікам гледачоў і падпісчыкамі, якія вызначаюць акцыі ў даходах ад рэкламы. Зацікаўленыя бакі токенаў DeHub атрымліваюць прапарцыйную долю агульнага прыбытку ад пратаколу.',
    mineTitle: 'Шахта праз змякчэнне змесціва',
    mineSubtitle: 'Дэцэнтралізаваная мадэль здабычы карысных выкапняў і долі даходаў',
    mineDesc1: 'Толькі некалькі кашалькоў ўтрымліваюць больш за 50 мільёнаў токенаў DeHub, большасць з якіх з \'яўляюцца аперацыйнымі кашалькамі, а астатнія вядомыя як члены супольнасці.',
    mineDesc2: 'Толькі ядро каманды або трымальнікі значка верхняга яруса будуць мець магчымасць імгненна выдаляць відэа, спальваючы звязанае з NFT. Пасля ўсе атрыманыя даходы ад рэкламы і любая гульня, каб зарабіць узнагароды, прывязаныя да відэа, будуць размеркаваны з усімі кашалькамі для галасавання, каб яшчэ больш стрымліваць дрэнных суб \'ектаў і стымуляваць зацікаўленую супольнасць.',
    mineDynamic: 'Колькасць токенаў DeHub, неабходных для ўсёй утыліты, з \'яўляецца дынамічнай зменнай, таму яна павінна быць зменена ў любы час у залежнасці ад кошту. Любыя змены будуць абвешчаныя публічна на ўсіх афіцыйных каналах.',
    govTitle: 'Канструкцыя сістэмы кіравання + мадэрацыі',
