    superPowersDesc: 'Суперздольнасці ператвараюць назапашвальны значок у дастатковую колькасць, якую вы можаце выдаткаваць. Кожныя два тыдні павялічваецца колькасць грантаў на ваш значок, і выдаткаваныя грошы размяшчаюць адзін слупок у слоце ў верхняй частцы хатняй стужкі. Каманда адкрыта для ўсіх і аб \'ядноўвае магутнасць кашалька да васьмі ўліковых запісаў, даючы кожнаму ўдзельніку значок сваіх агульных разблакоў. Слот круціцца: калі выконваецца некалькі імпульсаў, гледачам раздаецца адзін ўзважаны значок, таму больш высокі ўзровень адлюстроўваецца часцей, і кожны атрымлівае акно, якое яму было прадастаўлена.',
    superPowersDescV2: 'Суперздольнасці ператвараюць назапашвальны значок у дастатковую колькасць, якую вы можаце выдаткаваць. Кожныя два тыдні павялічваецца колькасць грантаў на ваш значок, і выдаткаваныя грошы размяшчаюць адзін слупок у слоце ў верхняй частцы хатняй стужкі. Каманда адкрыта для ўсіх і аб \'ядноўвае магутнасць кашалька да васьмі ўліковых запісаў, даючы кожнаму ўдзельніку значок сваіх агульных разблакоў. Слот круціцца: калі выконваецца некалькі імпульсаў, гледачам раздаецца адзін ўзважаны значок, таму больш высокі ўзровень адлюстроўваецца часцей, і кожны атрымлівае акно, якое яму было прадастаўлена.',
    boostPower: '1) Узмацненне',
    boostPowerDesc: 'Пастаўце паведамленне з апошняга тыдня ў верхняй частцы хатняй стужкі. Разблакіроўка ў Краба. Жыві зараз.',
    secondWindPower: '2) Другі вецер',
