    trendJacker: '4) Тэндэнцыйны куртка',
    trendJackerDesc2: 'Пастаўце адну з вашых катэгорый у верхняй частцы трэндавага спісу. Разблакіроўка ў Гіганцкай Чарадзе. Жыві зараз.',
    timelineBomber: '5) Бамбардзіроўшчык часовай шкалы',
    timelineBomberDesc2: 'Твае паслядоўнікі бачаць твой пост наперадзе кагосьці іншага — кароль Кобра біў Мегаладон для людзей, якія вырашылі пачуць ад цябе. Разблакіроўка ў Караля Кобры. Жыві цяпер.',
    precisionStrike: '8) Дакладны ўдар',
    precisionStrikeDesc: 'Звяжыцеся з людзьмі, якія сочаць за вашым уліковым запісам. Разблакіроўка ў Дэльфіне. Жыві зараз.',
    harpoon: '9) Гарпун',
    harpoonDesc: 'Паведаміце кожнаму ўладальніку ў значках, якія вы выбіраеце, пра адну пасаду. Разблакіроўка ў Тыгровай акуле. Жыві цяпер.',
    superPowersMore2: 'Усе дванаццаць сіл знаходзяцца ў прамым эфіры і пералічаныя ў праграме. Якар каментарыяў трымае ваш каментар у верхняй частцы чужой ніткі. Сігнальны ўспышка адпраўляе па адным апавяшчэнні на кожны ўліковы запіс, які ідзе за вамі. Куртка Flak робіць пост імунітэтам для пахавання ўніз галасы падчас яго запуску. Каманда дазваляе восем уліковых запісаў аб \'яднаць магутнасць кашалька, каб кожны ўдзельнік насіў значок, які аб\' ядноўвае баланс разблакоўкі. Пярэдняя радок ставіць Этап, які вы размяшчаеце, у верхняй частцы прыступкі. Глыбокі ток дае адзін з вашых імпульсаў на чужую пасаду.',
    superPowersMoreV2: 'Усе дванаццаць сіл знаходзяцца ў прамым эфіры і пералічаныя ў праграме. Якар каментарыяў трымае ваш каментар у верхняй частцы чужой ніткі. Сігнальны ўспышка адпраўляе па адным апавяшчэнні на кожны ўліковы запіс, які ідзе за вамі. Куртка Flak робіць пост імунітэтам для пахавання ўніз галасы падчас яго запуску. Каманда дазваляе восем уліковых запісаў аб \'яднаць магутнасць кашалька, каб кожны ўдзельнік насіў значок, які аб\' ядноўвае баланс разблакоўкі. Пярэдняя радок ставіць Этап, які вы размяшчаеце, у верхняй частцы прыступкі. Глыбокі ток дае адзін з вашых імпульсаў на чужую пасаду.',
