    spRotationTitle: 'Як падзяліць слот',
    spRotationDesc: 'Слот круціцца, а не штыфты. Калі адначасова выконваецца некалькі імпульсаў, кожнаму гледачу прысвойваецца адзін, абцяжараны ўзроўнем значка ўзмацняльніка — больш высокі ўзровень адлюстроўваецца часцей, і кожны па-ранейшаму атрымлівае акно, за якое заплаціў. Што купляе імпульс - гэта доля голасу на пэўную колькасць хвілін, а не адзінае валоданне верхняй часткай стужкі.',
    spCycleTitle: 'Адзін гадзіннік для ўсіх',
