    spSafetyTitle: 'Тое, што імпульс не можа зрабіць',
    spSafetyDesc: 'Кожны розыгрыш паўторна правяраецца на пост, як ён стаіць у гэты момант, таму пост, які з тых часоў быў выдалены, заблакаваны або адзначаны спелы, ніколі не трапляе ў стужку незнаёмца. Спелыя паведамленні таксама адмаўляюцца пры браніраванні, і імпульс ніколі не прадастаўляецца тым, хто заблакаваў вас ці чалавека, якога вы павялічылі.',
