    pegDesc1: 'Токен DeHub з \'яўляецца карысным маркерам. Для мэтаў у дадатку ён у цяперашні час прывязаны да $ 0.001 за маркер, што з\' яўляецца хуткасцю, якую вы бачыце пры куплі праз шлюз Fiat, і хуткасцю, якая выкарыстоўваецца для цэнаўтварэння ў дадатку. Гэтая прывязка існуе, каб захаваць эканоміку ў дадатку стабільнай і прадказальнай, пакуль сетка маштабуецца — гэта ўнутраная стаўка бухгалтарскага ўліку, а не падлога, гарантыя або абяцанне будучай кошту.',
    pegDesc2: 'Токены гандлююцца на дэцэнтралізаваных біржах, прычым басейны ліквіднасці населены з той самай базавай цаны 0.001 па некалькіх ланцужках. На адкрытым рынку цана ўсталёўваецца таргамі, а не DeHub, што азначае, што токены DeHub могуць гандляваць вышэй або ніжэй у дадатку ў любы час. DeHub выводзіць сваю афіцыйную ліквіднасць на DEXS, каб кожная транзакцыя заставалася публічна праверанай на ланцужку.',
    disclaimer: 'Адмова ад адказнасці',
    disclaimerNoApy: 'Важна: у той час як правядзенне токенаў DeHub дае права ўласнасці ў сетцы DeHub і дае права акцыянерам на долю прыбытку ад пратаколу, няма ўстаноўленага APY, няма гарантаванай стаўкі прыбытку і няма чакання прыбытку любога роду. Усе дыстрыбутывы цалкам залежаць ад прадукцыйнасці сеткі і даходаў, якія пратакол фактычна генеруе за дадзены перыяд. Узнагароды могуць быць ніжэй, чым у любым папярэднім перыядзе, і могуць быць нулявымі. Нішто на гэтай старонцы не з \'яўляецца абяцаннем, праекцыяй або прапановай вяртання, і нішто тут не з\' яўляецца фінансавай парадай.',
    disclaimerText: 'Токены DeHub прызначаны выключна для карысных мэтаў гэтак жа, як і любыя лічбавыя токены або валюты ў гульні або ў дадатку, і строга не з \'яўляюцца інвестыцыямі. Паколькі наш маркер жыве ў ланцугу, мы можам прапанаваць дадатковую ўтыліту, а таксама беспрэцэдэнтны ўзровень праверанай празрыстасці. Вышэйзгаданыя даныя збіраюцца выключна для празрыстасці, адукацыйных і інфармацыйных мэтаў. DeHub і ўсе філіялы не нясуць адказнасці за фінансавыя страты, панесеныя пры куплі якіх-небудзь токенаў або NFT, якія мы выпускаем. Рынкі вельмі зменлівыя. Вы таксама можаце страціць усе свае грошы з-за непрадбачаных памылак, такіх як збоі ў кампетэнтнасці, тэхнічныя памылкі, узломы і гэтак далей. Таму ты мусіш выдаткаваць толькі тое, што можаш дазволіць сабе страціць.',
